   MIDNIGHT  ·  post-draft line-up  (y el "draft anterior", que usa las mismas cartas)
   =========================================================================== */
:root[data-diseno="midnight"] #lu,
:root[data-diseno="midnight"] #pv{color:#eef2ff}
